toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-main {
    flex: 3;
    min-width: 0;
}

/* Filters sidebar */
.catalog-filters {
    flex: 1;
    max-width: 25%;
    border-right: 1px solid #e0e0e0;
    padding-right: 1.5rem;
}

.catalog-filters h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

.catalog-filters h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

.filter-placeholder {
    color: #888;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    gap: 0.75rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

.price-inputs input {
    width: 5.5rem;
    padding: 0.35rem;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: 1px solid #0d6efd;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #0d6efd;
    color: #fff;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    background: #fff;
    color: #0d6efd;
}

.btn-clear:hover {
    background: #f0f0f0;
}

/* Toolbar */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.35rem 0.5rem;
}

.results-summary {
    color: #555;
    font-size: 0.9rem;
}

/* Product grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

.product-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.15s;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.product-image {
    height: 160px;
    background: #f5f5f5;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.product-image img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.placeholder-text {
    color: #999;
    font-size: 0.85rem;
    text-align: center;
    padding: 0.5rem;
}

.product-info {
    padding: 0.75rem;
}

.product-name {
    font-size: 1rem;
    margin: 0 0 0.35rem;
}

.product-price {
    font-weight: 600;
    margin: 0 0 0.25rem;
    color: #222;
}

.product-rating {
    color: #f5a623;
    margin: 0 0 0.35rem;
    font-size: 1.1rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    margin-bottom: 0.4rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #198754;
    background: #198754;
    color: #fff;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add-to-cart:hover:not(:disabled) {
    background: #157347;
}

.btn-add-to-cart:disabled {
    background: #ccc;
    border-color: #ccc;
    cursor: not-allowed;
}

/* Pagination */
.catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ddd;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-page:hover:not(:disabled):not(.active) {
    background: #f0f0f0;
}

.btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.btn-page:disabled {
    color: #bbb;
    cursor: not-allowed;
}

/* State displays */
.catalog-loading,
.empty-results,
.catalog-error {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

.catalog-error {
    color: #dc3545;
}

.catalog-error button {
    margin-top: 0.75rem;
    padding: 0.4rem 1rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

